from pathlib import Path
from typing import Optional, Union

from ..mapping import Mapping
from . import MODEL_MAP
from .modeling_utils import QuantConfig


class AutoConfig:

    @staticmethod
    def from_hugging_face(hf_model_or_dir,
                          dtype: str = 'auto',
                          mapping: Optional[Mapping] = None,
                          quant_config: Optional[QuantConfig] = None,
                          **kwargs):
        import transformers
        trust_remote_code = kwargs.get('trust_remote_code', False)

        hf_config = transformers.AutoConfig.from_pretrained(
            hf_model_or_dir, trust_remote_code=trust_remote_code)

        if hasattr(hf_config,
                   'architectures') and hf_config.architectures is not None:
            hf_arch = hf_config.architectures[0]
        elif hasattr(hf_config,
                     'model_type') and hf_config.model_type.find('mamba') != -1:
            hf_arch = 'MambaForCausalLM'

        trtllm_model_cls = MODEL_MAP.get(hf_arch, None)
        if trtllm_model_cls is None:
            raise NotImplementedError(
                f"The given huggingface model architecture {hf_arch} is not supported in TRT-LLM yet"
            )

        if not hasattr(trtllm_model_cls, 'config_class'):
            raise NotImplementedError(
                f"The given TRT-LLM model class {trtllm_model_cls} does not support AutoConfig"
            )

        trtllm_cfg_cls = getattr(trtllm_model_cls, 'config_class')
        if not hasattr(trtllm_cfg_cls, 'from_hugging_face'):
            raise NotImplementedError(
                f"The given TRT-LLM model class {trtllm_cfg_cls} does not support from_hugging_face"
            )

        return trtllm_cfg_cls.from_hugging_face(hf_model_or_dir, dtype, mapping,
                                                quant_config, **kwargs)


class AutoModelForCausalLM:

    @staticmethod
    def get_trtllm_model_class(hf_model_or_dir: Union[str, Path],
                               trust_remote_code: bool = False):
        import transformers

        hf_model_or_dir = Path(hf_model_or_dir) if not isinstance(
            hf_model_or_dir, Path) else hf_model_or_dir

        assert (hf_model_or_dir / "config.json").exists(
        ), "Please provide a Hugging Face model as the input to the LLM API."

        hf_config = transformers.AutoConfig.from_pretrained(
            hf_model_or_dir, trust_remote_code=trust_remote_code)
        if hasattr(hf_config,
                   'architectures') and hf_config.architectures is not None:
            hf_arch = hf_config.architectures[0]
        elif hasattr(hf_config,
                     'model_type') and hf_config.model_type.find('mamba') != -1:
            hf_arch = 'MambaForCausalLM'

        trtllm_model_cls = MODEL_MAP.get(hf_arch, None)

        if trtllm_model_cls is None:
            raise NotImplementedError(
                f"The given huggingface model architecture {hf_arch} is not supported in TRT-LLM yet"
            )
        return trtllm_model_cls

    @staticmethod
    def from_hugging_face(hf_model_or_dir,
                          dtype: str = 'auto',
                          mapping: Optional[Mapping] = None,
                          quant_config: Optional[QuantConfig] = None,
                          **kwargs):
        trtllm_model_cls = AutoModelForCausalLM.get_trtllm_model_class(
            hf_model_or_dir)

        if not hasattr(trtllm_model_cls, 'from_hugging_face'):
            raise NotImplementedError(
                f"The given {trtllm_model_cls} does not support from_hugging_face yet"
            )

        return trtllm_model_cls.from_hugging_face(hf_model_or_dir, dtype,
                                                  mapping, quant_config,
                                                  **kwargs)

from typing import Generic, Optional, Type

from ..model_config import ModelConfig
from ..utils import model_extra_attrs
from .modeling_utils import (MODEL_CLASS_MAPPING,
                             MODEL_CLASS_VISION_ENCODER_MAPPING,
                             DecoderModelForCausalLM, TConfig, TModel)


class AutoModelForCausalLM(Generic[TModel, TConfig]):

    @staticmethod
    def _resolve_class(config: ModelConfig) -> Optional[Type]:
        """Internal: Resolve the model class for a config without instantiating."""
        pretrained_config = config.pretrained_config
        if not pretrained_config.architectures:
            return None

        model_arch = pretrained_config.architectures[0]

        if config.mm_encoder_only:
            vision_encoder_info = MODEL_CLASS_VISION_ENCODER_MAPPING.get(
                model_arch)
            if vision_encoder_info is None:
                return None
            vision_encoder_cls, _ = vision_encoder_info
            return vision_encoder_cls

        # Hack to detect eagle3 checkpoints. TODO: should we provide
        # our own checkpoints with the correct arch? It would let us
        # avoid nasty stuff like this.
        if hasattr(pretrained_config, "draft_vocab_size"):
            model_arch = model_arch.replace("Eagle3",
                                            "")  # Strip the appended EAGLE3
            model_arch = "EAGLE3" + model_arch

        if model_arch in (
                "DeepseekV3ForCausalLM", "Glm4MoeForCausalLM",
                "ExaoneMoEForCausalLM"
        ) and config.spec_config is not None and config.spec_config.max_draft_len == 0:
            model_arch = "MTPDraftModelForCausalLM"

        return MODEL_CLASS_MAPPING.get(model_arch)

    @staticmethod
    def from_config(
        config: ModelConfig[TConfig],
    ) -> DecoderModelForCausalLM[TModel, TConfig]:
        if config.mm_encoder_only:
            model_arch = config.pretrained_config.architectures[0]
            vision_encoder_info = MODEL_CLASS_VISION_ENCODER_MAPPING.get(
                model_arch)
            if vision_encoder_info is None:
                raise ValueError(
                    f"Unknown architecture for AutoModelForMultimodalEncoder: {model_arch}"
                )
            vision_encoder_cls, vlm_base_model = vision_encoder_info
            return vision_encoder_cls(config, vlm_base_model)
        cls = AutoModelForCausalLM._resolve_class(config)
        if cls is None:
            raise ValueError(
                f"Unknown architecture for AutoModelForCausalLM: {config.pretrained_config.architectures[0]}"
            )
        if issubclass(cls, DecoderModelForCausalLM):
            config._frozen = False
            config.skip_create_weights_in_init = True
            config._frozen = True
        extra_attrs = config.extra_attrs
        with model_extra_attrs(extra_attrs):
            model = cls(config)
        model.extra_attrs = extra_attrs
        return model
